// SL-3: renderVerdict is wrapped further down to rebuild all five charts, so every slider tick
// destroyed and re-created them -- 8.7 to 14.5 ms a tick with six players picked, against 0.9 ms
// with none, and a phone is several times slower than the Mac that was measured on. While a slider
// is moving the wrapper defers the rebuild; the change event at release, and a trailing timer,
// bring the charts up to date. Picks and toggles still rebuild at once.
$('blendSlider').addEventListener('input', (e) => {
  BLEND = parseInt(e.target.value, 10);
  updateLabels();
  gnRefreshOpenResults();
  window.GN_SLIDING = true;
  try { renderPicked('A'); renderPicked('B'); renderVerdict(); } finally { window.GN_SLIDING = false; }
  try { localStorage.setItem('gn-trade-blend', String(BLEND)); } catch(e) {}
});

$('yearsSlider').addEventListener('input', (e) => {
  YEARS = parseInt(e.target.value, 10);
  updateLabels();
  gnRefreshOpenResults();
  window.GN_SLIDING = true;
  try { renderPicked('A'); renderPicked('B'); renderVerdict(); } finally { window.GN_SLIDING = false; }
  try { localStorage.setItem('gn-trade-years', String(YEARS)); } catch(e) {}
});
['blendSlider','yearsSlider'].forEach(id => $(id).addEventListener('change', () => { if (typeof gnChartsNow === 'function') gnChartsNow(); }));

try {
  const saved = JSON.parse(localStorage.getItem('gn-trade-state') || '{}');
  if (saved.A && Array.isArray(saved.A)) state.A = gnResolveSaved(saved.A);
  if (saved.B && Array.isArray(saved.B)) state.B = gnResolveSaved(saved.B).filter(p => !state.A.some(a => gnPKey(a) === gnPKey(p)));
  const savedMode = localStorage.getItem('gn-trade-mode');
  if (savedMode === 'dollar') {
    MODE = 'dollar';
    [...$('modeToggle').querySelectorAll('button')].forEach(b => b.classList.toggle('active', b.dataset.mode === MODE));
  }
  const savedBlend = parseInt(localStorage.getItem('gn-trade-blend') || '0', 10);
  if (!isNaN(savedBlend) && savedBlend >= 0 && savedBlend <= 100) {
    BLEND = savedBlend;
    $('blendSlider').value = String(BLEND);
  }
  const savedYears = parseInt(localStorage.getItem('gn-trade-years') || '1', 10);
  if (!isNaN(savedYears) && savedYears >= 1 && savedYears <= 10) {
    YEARS = savedYears;
    $('yearsSlider').value = String(YEARS);
  }
  const savedYearMode = localStorage.getItem('gn-trade-year-mode');
  if (savedYearMode === 'single' || savedYearMode === 'cumulative') {
    YEAR_MODE = savedYearMode;
    [...$('yearModeToggle').querySelectorAll('button')].forEach(b => b.classList.toggle('active', b.dataset.mode === YEAR_MODE));
  }
  const savedFadeMode = localStorage.getItem('gn-trade-fade-mode');
  if (savedFadeMode === 'on' || savedFadeMode === 'off') {
    FADE_MODE = savedFadeMode;
    [...$('fadeModeToggle').querySelectorAll('button')].forEach(b => b.classList.toggle('active', b.dataset.mode === FADE_MODE));
  }
} catch(e) {}
updateLabels();
renderPicked('A'); renderPicked('B'); renderVerdict();


// ====================== CHARTS ======================
let TIME_RANGE = '30d';
let chartPlayer, chartTeamTotal, chartStacked;

// ---------- GNDAILY daily-value engine (per-player $ series over the season to date, GNDAILY.days days) ----------
// Active window for Player-value + Team-total charts. 'season' = every day on file; otherwise last N.
let GN_RANGE = 'season';
// Reverse map: team base36 char -> teamId (string). '.' = free agent / unrostered.
const GN_CHAR2TEAM = (function(){ const m={}; for(const tid in GNDAILY.teams){ m[GNDAILY.teams[tid].ch]=tid; } return m; })();
// Daily $ series for a player: shape series if present, else flat at p.d.
// v50.20: both helpers divide by RAW_PER_DOLLAR. They divided by GNDAILY.raw (637.32), a constant that
// never matched the calculator's anchor, so the EKG's $ line ran ~21% below the manager bar for the same roster.
function gnDailyDollars(p){
  const sh = GNDAILY.shape[String(p.eid)];
  if(!sh) return Array.from({length:GNDAILY.days}, () => p.d);
  return Array.from({length:GNDAILY.days}, (_,i) => (p.r * (1 + sh[i]/100)) / RAW_PER_DOLLAR);
}
// $ value of player p on a single day index i (0-based).
function gnDollarOnDay(p, i){
  const sh = GNDAILY.shape[String(p.eid)];
  return sh ? (p.r * (1 + sh[i]/100)) / RAW_PER_DOLLAR : p.d;
}
// Window of the daily series for the active GN_RANGE: returns {start,end} day indices (end exclusive).
function gnWindow(){
  const D = GNDAILY.days;
  if(GN_RANGE === 'season') return { start:0, end:D };
  const n = parseInt(GN_RANGE, 10) || D;
  return { start: Math.max(0, D - n), end: D };
}
// Which team (teamId string) is player eid on at day number d (1..GNDAILY.days)? null = FA/unrostered.
function gnTeamOnDay(eid, d){
  const rle = GNDAILY.member[String(eid)];
  if(!rle) return null;
  const segs = rle.split(',');
  let curChar = null;
  for(let k=0;k<segs.length;k++){
    const seg = segs[k];
    const ch = seg.charAt(0);
    const startDay = parseInt(seg.slice(1), 10);
    if(startDay <= d) curChar = ch; else break;
  }
  if(curChar === null || curChar === '.') return null;
  return GN_CHAR2TEAM[curChar] || null;
}
let chartMgrEkg = null;
let MGR_EKG_ORG = null; // org name whose EKG is currently shown (null = hidden)

const PALETTE = ['#0B2C5C','#C81029','#E5A227','#1E7B3E','#2C6E7F','#7A1E2B','#44587A','#9C6B1E','#5A6E2A','#5B3A6E','#107E7D','#A6471F','#324A6D','#8A6D1C','#3F6E4A','#6E2F4A','#1F5A6E','#B0541F','#4A5A2A','#6E4A2A'];
const COLOR_A = '#2f4f4f';
const COLOR_B = '#c0392b';

// v50.20: the snapshot-based history charts were retired when the career arc / 2026 daily views shipped;
// their parser and filter (parseSnapshot, valueAtSnapshot, getFilteredSnapshots, buildLabels, TIME_RANGE) were
// dead code and are removed. HISTORY itself moved out to gn-history.js in v50.23; the footnote
// reads GN_HISTORY_DATES, which the refresh derives from the same snapshots.

// CHT-1: axis ticks used to be toFixed(0) everywhere. In $ mode values are raw/527.08,
// so the entire league sits between $0.00 and $3.81 and the player/team arcs rendered nine
// identical "$0" gridline labels -- while the tooltip on the same chart showed 2dp. Rather
// than a magnitude cutoff, take the decimals from the axis's own ticks: the fewest places
// that keep every label on that axis distinct. Manager totals step by $50 and stay whole;
// an arc stepping by $0.05 gets two places.
function gnAxisDecimals(ticks, v){
  if (ticks && ticks.length > 1) {
    const vals = [];
    for (let i = 0; i < ticks.length; i++) {
      const t = ticks[i] && ticks[i].value;
      if (typeof t === 'number' && isFinite(t)) vals.push(t);
    }
    if (vals.length > 1) {
      for (let d = 0; d <= 3; d++) {
        const seen = Object.create(null);
        let dup = false;
        for (let j = 0; j < vals.length; j++) {
          const s = vals[j].toFixed(d);
          if (seen[s]) { dup = true; break; }
          seen[s] = 1;
        }
        if (!dup) return d;
      }
      return 3;
    }
  }
  const a = Math.abs(v);
  return (a > 0 && a < 10) ? 2 : 0;
}
function gnAxisTick(unit, v, ticks){
  if (typeof v !== 'number' || !isFinite(v)) return unit + v;
  return unit + v.toFixed(gnAxisDecimals(ticks, v));
}
function fmtYAxis(v, i, ticks) {
  return gnAxisTick(MODE === 'dollar' ? '$' : '', v, ticks);
}
// CHT-3 / CHT-5: the four .no-data-msg elements carry their default copy in the markup, so
// anything that swaps in a situational message has to be able to put the default back --
// otherwise the next empty state shows the previous situation's sentence.
function gnNoData(el, msg){
  if (!el) return;
  if (el.dataset.defaultMsg === undefined) el.dataset.defaultMsg = el.textContent;
  el.textContent = (msg == null) ? el.dataset.defaultMsg : msg;
  el.style.display = 'block';
}
function gnNoDataHide(el){
  if (!el) return;
  if (el.dataset.defaultMsg !== undefined) el.textContent = el.dataset.defaultMsg;
  el.style.display = 'none';
}
// CHT-4: the career arc and the 2026 timeview plot dynasty values whatever MODE says --
// gnCareerArc is a 10-year trajectory and seasonSeries a daily GNDAILY shape, and ROS '26
// is a single rest-of-season projection with neither. They cannot follow ROS, so the axis
// says what it is rather than leaving the reader to assume it matches the totals above.
function gnValueAxisTitle(){
  if (MODE === 'ros') return 'Risk-Adj \u2014 dynasty values, not ROS';
  // SL-2: gnCareerArc anchors on the 2026 value and follows the engine's RA shape, so neither
  // slider reaches these two charts while the stacked bar and the totals follow both. At 100% Pure
  // and ten years the side total read 17,110 and the stacked bar 7,872 for a player whose arc still
  // started at 1,111 under a bare "Risk-Adj". The title says so once a slider is off its default.
  const base = MODE === 'dollar' ? '$ value' : 'Risk-Adj';
  return (BLEND > 0 || YEARS > 1) ? base + ' \u2014 2026 anchor, sliders not applied' : base;
}

function renderPlayerChart() { return gnRenderArcPlayer(); }
function renderTeamTotalChart() { return gnRenderArcTeam(); }

// ============ 20-year career-value arc (10 past + 10 future) ============
function gnGrowthDiv(age, pit){
  age = Math.round(age);
  if(pit) return age<=19?1.35:age<=21?1.30:({22:1.25,23:1.20,24:1.15,25:1.10,26:1.05}[age]||1.0);
  return age<=19?1.30:age<=21?1.25:({22:1.20,23:1.15,24:1.10,25:1.05}[age]||1.0);
}
const GN_VET_DEC=[1.0,0.950,0.902,0.830,0.764,0.703,0.597,0.508,0.432,0.324];   // v50.20: the separate steeper veteran curve is retired (methodology 12); one curve for every peak-anchored player
const GN_T3_DEC =[1.0,0.948,0.901,0.829,0.764,0.702,0.596,0.507,0.431,0.323];
function gnAgeFactorCanon(age, pit, dec){   // canonical ramp-then-decline (future fallback only)
  const peak = pit?27:26;
  if(age<=peak) return 1/gnGrowthDiv(age,pit);
  const k = Math.round(age)-peak;
  if(k<dec.length) return dec[k];
  return Math.max(0, dec[dec.length-1]*Math.pow(0.55,k-dec.length+1));
}
const GN_NOW_Y=2026, GN_Y_LO=2016, GN_Y_HI=2036;
const GN_ARC_YEARS=(function(){var a=[];for(var y=GN_Y_LO;y<=GN_Y_HI;y++)a.push(String(y));return a;})();
const GN_NOW_IDX = GN_NOW_Y - GN_Y_LO;
function gnCareerArc(p){
  const pit  = !!(p.p) && p.p.indexOf('P')>=0;
  const peak = pit?27:26;
  const dec  = (p.t==='T1'||p.t==='T2')?GN_VET_DEC:GN_T3_DEC;
  const age  = (p.a!=null?p.a:27);
  const cur  = (MODE==='dollar') ? (p.d||0) : (p.r||0);   // 2026 anchor = displayed value (respects RA/$)
  // PAST: development ramp that rises to the current value and plateaus at peak (never exceeds current -> no blow-up)
  const pastF = a => (a>=peak ? 1.0 : 1/gnGrowthDiv(a,pit));
  const anchorPast = pastF(age) || 1;
  // FUTURE: use the engine's own forward trajectory shape (tj); fallback to canonical curve if tj missing
  const tj = (p.tj && p.tj.length>=10 && p.tj[0]>5) ? p.tj : null;
  const futR = k => {
    if(tj){ return k<=9 ? tj[k]/tj[0] : (tj[9]/tj[0])*((tj[8]>0)?(tj[9]/tj[8]):1); }
    const a0 = gnAgeFactorCanon(age,pit,dec)||1; return gnAgeFactorCanon(age+k,pit,dec)/a0;
  };
  // TT-6: T4/T5 means "not established", not "has never played", and the tier alone decided that a
  // player had NO past at all. Right for the 709 T4s aged 25 and under; wrong for the 235 T4/T5
  // players who are older -- Craig Kimbrel at 38, Sandy Leon at 37, Mike Clevinger at 35. Only 54 of
  // the 763 T4s are over 25, while 181 of the 203 T5s are, because T5 is a fringe tier rather than a
  // prospect one. Keep the no-past treatment for genuine prospects; everyone else gets the
  // age-implied debut this same line already uses. Affects both value-over-time cards, by design:
  // an old player who materialises out of nowhere in 2026 is wrong on either of them.
  const prospect = (p.t==='T4'||p.t==='T5') && Math.round(age) <= 25;
  let onset = prospect ? GN_NOW_Y : (GN_NOW_Y - Math.max(0, Math.round(age)-22));
  onset = Math.max(GN_Y_LO, Math.min(GN_NOW_Y, onset));
  const vals=[];
  for(let y=GN_Y_LO;y<=GN_Y_HI;y++){
    const dy = y-GN_NOW_Y;
    if(y<onset){ vals.push(null); }
    else if(dy<=0){ vals.push(cur * pastF(age+dy) / anchorPast); }
    else { vals.push(cur * futR(dy)); }
  }
  return vals;
}
const gnFutureShade = {
  id:'gnFutureShade',
  beforeDatasetsDraw(chart){
    const xs=chart.scales.x, a=chart.chartArea; if(!xs||!a) return;
    const xb = xs.getPixelForValue(GN_NOW_IDX);
    const ctx=chart.ctx; ctx.save();
    ctx.fillStyle='rgba(120,140,170,0.12)';
    ctx.fillRect(xb, a.top, a.right-xb, a.bottom-a.top);
    ctx.strokeStyle='rgba(120,140,170,0.5)'; ctx.setLineDash([3,3]); ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(xb,a.top); ctx.lineTo(xb,a.bottom); ctx.stroke();
    ctx.restore();
  }
};
// PV-4: PALETTE holds twenty colours and the datasets indexed into it with i % length, so the
// twenty-first pick drew in the same navy as the first -- Ohtani and Garrett Crochet, indistinguishable.
// Past the palette, rotate hue by a step coprime with 360 so every further line gets its own colour.
function gnSeriesColor(i){
  if (i < PALETTE.length) return PALETTE[i];
  return 'hsl(' + ((i * 47) % 360) + ',55%,38%)';
}
// SB-2: the stacked bars want the same colour at 80% alpha. A hex takes a suffix; the generated
// hsl() past the palette does not, so it becomes hsla() instead of silently producing a bad value.
function gnSeriesFill(i){
  const c = gnSeriesColor(i);
  return c.charAt(0) === '#' ? c + 'cc' : c.replace('hsl(', 'hsla(').replace(')', ',0.8)');
}
// PV-3: the tooltips printed toFixed(2) in every mode, so a Risk-Adj point read 1160.37 beside an
// axis reading 1160 and side totals reading 1,160. Money keeps its cents; everything else rounds
// and takes separators, matching fmtValue.
function gnChartNum(unit, v){
  if (v == null) return '-';
  return unit === '$' ? '$' + v.toFixed(2) : Math.round(v).toLocaleString();
}
// PV-1: a missing daily shape is a missing VALUE SERIES, which is not the same claim as "no games".
// 1,538 of the 2,118 board records carry no shape and 842 of those show games, at-bats or innings
// (JR Ritchie 14 games and 58 innings; Joe Mack 90 games and 264 at-bats). Say which case it is.
function gnPlayedIn2026(p){ return (p.gp||0) > 0 || (p.ab||0) > 0 || (p.ip||0) > 0 || (p.fp25||0) > 0; }
function gnFlatNote(p){ return gnPlayedIn2026(p) ? ' \u2014 flat: no daily history on file' : ' \u2014 flat: no 2026 games'; }
// PV-5: the wrap is a fixed 220px and Chart.js draws the legend inside it, so twelve picks left a
// 116px plot and twenty-four left 76px. Give the box room per legend row instead, up to a cap.
function gnFitChartWrap(canvasId, n){
  const cv = document.getElementById(canvasId); if (!cv) return;
  const wrap = cv.closest('.chart-canvas-wrap'); if (!wrap) return;
  wrap.style.height = n ? Math.min(420, 220 + Math.max(0, n - 6) * 14) + 'px' : '';
}
// PV-7: a one-line description of what the canvas is showing, for anything that cannot see it.
function gnDescribeChart(canvasId, text){
  const cv = document.getElementById(canvasId); if (cv) cv.setAttribute('aria-label', text);
}
function gnArcNames(list){
  const shown = list.slice(0, 8).map(p => p.n);
  return shown.join(', ') + (list.length > shown.length ? ' and ' + (list.length - shown.length) + ' more' : '');
}
function gnArcDataset(label, data, color, w){
  return { label, data, borderColor: color, backgroundColor: color+'22',
    borderWidth: w||2.4, pointRadius: 0, pointHoverRadius: 4, tension: 0.28, spanGaps: false, fill: false,
    segment: { borderDash: ctx => (ctx.p0DataIndex >= GN_NOW_IDX ? [5,4] : undefined) } };
}
function gnArcOptions(unit, legendSize){
  return { responsive:true, maintainAspectRatio:false, interaction:{mode:'nearest',intersect:false},
    plugins:{ legend:{position:'bottom',labels:{font:{size:legendSize||10},boxWidth:12}},
      tooltip:{callbacks:{ title:(items)=>items.length?GN_ARC_YEARS[items[0].dataIndex]+(items[0].dataIndex>GN_NOW_IDX?' (proj.)':(items[0].dataIndex<GN_NOW_IDX?' (past)':'')):'' ,
        label:(c)=>c.dataset.label+': '+gnChartNum(unit, c.parsed.y),
        // TT-1: a career year sums only the players whose arc has started, so the line steps up when
        // a player ENTERS it rather than when value grows. 1,868 of the 2,118 records start after
        // 2016, so nearly every multi-player side steps. Datasets that carry gnCounts say how many
        // players stand behind the point; the player card sets none and is unaffected.
        footer:(items)=>{
          const seen = {}, rows = [];
          items.forEach(it => {
            const c = it.dataset.gnCounts;
            if (!c || c[it.dataIndex] == null || seen[it.datasetIndex]) return;
            seen[it.datasetIndex] = 1;
            rows.push(c[it.dataIndex] + ' of ' + it.dataset.gnTotal + ' players counted');
          });
          return rows;
        } }} },
    scales:{ y:{ ticks:{font:{size:10},callback:(v,i,ticks)=>gnAxisTick(unit,v,ticks)}, beginAtZero:false,
          title:{display:true,text:gnValueAxisTitle(),font:{size:10}} },
      x:{ type:'category', ticks:{font:{size:9},maxTicksLimit:11,autoSkip:true} } } };
}
function gnRenderArcPlayer(){
  const ctx = document.getElementById('playerChart').getContext('2d');
  const allPlayers = [...state.A, ...state.B];
  const emptyMsg = document.getElementById('playerChartEmpty');
  if (allPlayers.length === 0){
    if(chartPlayer){chartPlayer.destroy();chartPlayer=null;}
    gnFitChartWrap('playerChart', 0);
    gnDescribeChart('playerChart', 'Player value over time. No players picked yet.');
    gnNoData(emptyMsg); return;
  }
  gnNoDataHide(emptyMsg);
  const unit = (MODE==='dollar')?'$':'';
  gnFitChartWrap('playerChart', allPlayers.length);
  const datasets = allPlayers.map((p,i)=>{
    const isA = state.A.some(x=>x.n===p.n && x.o===p.o);
    return gnArcDataset(p.n+' ('+(isA?'A':'B')+')', gnCareerArc(p), gnSeriesColor(i));
  });
  gnDescribeChart('playerChart', 'Player value over time, career view. ' + GN_ARC_YEARS[0] + ' to '
    + GN_ARC_YEARS[GN_ARC_YEARS.length-1] + ', ' + gnValueAxisTitle() + '. '
    + allPlayers.length + (allPlayers.length===1?' player: ':' players: ') + gnArcNames(allPlayers) + '.');
  const config = { type:'line', data:{labels:GN_ARC_YEARS, datasets}, options:gnArcOptions(unit,10), plugins:[gnFutureShade] };
  if(chartPlayer){ chartPlayer.destroy(); } chartPlayer = new Chart(ctx, config);
}
function gnRenderArcTeam(){
  const ctx = document.getElementById('teamTotalChart').getContext('2d');
  const emptyMsg = document.getElementById('teamTotalEmpty');
  if (state.A.length===0 && state.B.length===0){
    if(chartTeamTotal){chartTeamTotal.destroy();chartTeamTotal=null;}
    gnDescribeChart('teamTotalChart', 'Team total over time. No players picked yet.');
    gnNoData(emptyMsg); return;
  }
  gnNoDataHide(emptyMsg);
  const unit = (MODE==='dollar')?'$':'';
  // TT-1: carry the per-year contributor count alongside the sum, so the tooltip can say how much
  // of the side is actually in each point instead of leaving a roster-entry step to read as growth.
  function teamSeries(players){
    const sums = new Array(GN_ARC_YEARS.length).fill(null);
    const counts = new Array(GN_ARC_YEARS.length).fill(0);
    players.forEach(p=>{ const arc=gnCareerArc(p); for(let k=0;k<arc.length;k++){ if(arc[k]!=null){ sums[k]=(sums[k]||0)+arc[k]; counts[k]++; } } });
    return { sums, counts };
  }
  const datasets=[]; let stepped=false;
  // TT-2: the season view of this same card calls these "Side A receives"; so does every other
  // surface on the page. "Team A total" was this one card's private vocabulary.
  [['A', state.A, COLOR_A], ['B', state.B, COLOR_B]].forEach(([side, list, color])=>{
    if(!list.length) return;
    const s = teamSeries(list);
    const d = gnArcDataset('Side ' + side + ' receives (' + list.length + ')', s.sums, color, 3);
    d.gnCounts = s.counts; d.gnTotal = list.length;
    const entered = s.counts.filter(c=>c>0);
    if(entered.length && Math.min.apply(null, entered) < list.length) stepped = true;
    datasets.push(d);
  });
  const options = gnArcOptions(unit,11);
  if(stepped){
    options.plugins.subtitle = { display:true, color:'#6e6d68', font:{size:10,style:'italic'}, padding:{bottom:4},
      text:'Earlier years count only the players who had started by then, so the line steps up as they enter' };
  }
  const allPicked = state.A.concat(state.B);
  gnDescribeChart('teamTotalChart', 'Team total over time, career view. ' + GN_ARC_YEARS[0] + ' to '
    + GN_ARC_YEARS[GN_ARC_YEARS.length-1] + ', ' + gnValueAxisTitle() + '. Side A ' + state.A.length
    + ', Side B ' + state.B.length + ' players.' + (stepped ? ' Earlier years count fewer players.' : ''));
  const config = { type:'line', data:{labels:GN_ARC_YEARS, datasets}, options, plugins:[gnFutureShade] };
  if(chartTeamTotal){ chartTeamTotal.destroy(); } chartTeamTotal = new Chart(ctx, config);
}

function renderStackedBarChart() {
  const ctx = document.getElementById('stackedBarChart').getContext('2d');
  const emptyMsg = document.getElementById('stackedBarEmpty');
  if (state.A.length === 0 && state.B.length === 0) {
    if (chartStacked) { chartStacked.destroy(); chartStacked = null; }
    gnFitChartWrap('stackedBarChart', 0);
    gnDescribeChart('stackedBarChart', 'Trade comparison, stacked by player. No players picked yet.');
    gnNoData(emptyMsg);
    return;
  }
  gnNoDataHide(emptyMsg);

  const unit = (MODE === 'dollar') ? '$' : '';
  // SB-4: "Team A" was this card's private wording. Every other surface says "Side A receives",
  // and the count makes a one-sided proposal explain its own empty row.
  const labels = ['Side A receives (' + state.A.length + ')', 'Side B receives (' + state.B.length + ')'];
  const datasets = [];
  // Combined player list for consistent coloring
  const allPlayers = [];
  state.A.forEach(p => allPlayers.push({ p, side: 'A' }));
  state.B.forEach(p => allPlayers.push({ p, side: 'B' }));
  let unprojected = 0, sumA = 0, sumB = 0;
  allPlayers.forEach((item, i) => {
    const val = getValue(item.p);
    // SB-1: in ROS mode getValue is null for 42% of the board. Such a player drew no segment but
    // kept his legend swatch, so the card showed three players and two bars with nothing saying
    // why. Name it on his own legend entry, the way the value cards label a gap.
    if (val == null) unprojected++;
    else if (item.side === 'A') sumA += val; else sumB += val;
    // SB-7: bare names on the one card whose whole job is comparing two sides
    const label = item.p.n + ' (' + item.side + ')' + (val == null ? ' \u2014 no ROS projection' : '');
    const data = item.side === 'A' ? [val, 0] : [0, val];
    datasets.push({
      label: label,
      data,
      backgroundColor: gnSeriesFill(i),
      borderColor: gnSeriesColor(i),
      borderWidth: 1
    });
  });
  // SB-3: every player is a dataset here, so the legend crowds this card harder than its
  // neighbours -- twenty-four picks left a 74px plot in the fixed 220px box.
  gnFitChartWrap('stackedBarChart', allPlayers.length);
  gnDescribeChart('stackedBarChart', 'Trade comparison, stacked by player. '
    + labels[0] + ' totalling ' + gnChartNum(unit, sumA) + ', ' + labels[1] + ' totalling '
    + gnChartNum(unit, sumB) + '.' + (unprojected ? ' ' + unprojected + ' with no ROS projection.' : ''));

  const config = {
    type: 'bar',
    data: { labels, datasets },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { font: { size: 10 }, boxWidth: 12 } },
        // SB-1: the side cards mark an unprojected total with a floor sign; these bars are the same
        // floor and said nothing. They agree numerically, so this is what was missing, not the math.
        subtitle: unprojected
          ? { display: true, color: '#6e6d68', font: { size: 10, style: 'italic' }, padding: { bottom: 4 },
              text: unprojected + (unprojected === 1 ? ' picked player has' : ' picked players have')
                + ' no ROS projection, so the bars show a floor' }
          : { display: false },
        tooltip: {
          callbacks: {
            // SB-1: Math.round(null) printed a confident 0 for a player nothing was projected for,
            // the same conflation the verdict box was fixed for. SB-5: 1160 became 1,160.
            label: (ctx) => ctx.dataset.label + ': '
              + (ctx.parsed.x == null ? 'n/a' : gnChartNum(unit, ctx.parsed.x))
          }
        }
      },
      scales: {
        x: { stacked: true, ticks: { font: { size: 10 }, callback: fmtYAxis }, beginAtZero: true },
        y: { stacked: true, ticks: { font: { size: 12 } } }
      }
    }
  };
  // reassigning .options on a live chart does not reliably re-resolve plugin blocks, and the
  // subtitle above has to appear and disappear with the picks, so rebuild like the other cards do
  if (chartStacked) { chartStacked.destroy(); }
  chartStacked = new Chart(ctx, config);
}

// ====================== MANAGER COMPARISON CHART ======================
let MGR_LEVEL = 'org';
let MGR_ROSTERS=[], MGR_COUNTS=[], MGR_LABELS=[], MGR_DATA=[], MGR_MISSING=[], DEPTH_ORG=null;
const LEVEL_LABELS = {org:'Full org', mlb:'MLB roster', aaa:'AAA roster', optimized:'22-Man (fieldable)', keeper30:'30-Man (keeper)', opt30:'30-Man (fieldable)'};
let MGR_POS = '';
let chartMgr;

const MANAGER_ORGS = ['River Cats','KC Gray Hotdogs','MidwestBears','Kansas Sunflower Seeds','High Cheddar','Balking Dead','Dirty Spikes','C-Town Liquors'];
const MGR_COLORS = {
  'River Cats': '#FD5A1E',
  'KC Gray Hotdogs': '#004687',
  'MidwestBears': '#0E3386',
  'Kansas Sunflower Seeds': '#005A9C',
  'High Cheddar': '#EB6E1F',
  'Balking Dead': '#002B5C',
  'Dirty Spikes': '#13274F',
  'C-Town Liquors': '#333366'
}
const MGR_BORDER = {
  'River Cats': '#27251F',
  'KC Gray Hotdogs': '#BD9B60',
  'MidwestBears': '#CC3433',
  'Kansas Sunflower Seeds': '#EF3E42',
  'High Cheddar': '#002D62',
  'Balking Dead': '#D31145',
  'Dirty Spikes': '#CE1141',
  'C-Town Liquors': '#000000'
};

// Use real Roster Level designations from workbook (col l = "MLB" or "AAA")
function isMLBLevel(p) { return p.l === 'MLB'; }
function isAAALevel(p) { return p.l === 'AAA'; }

// Optimized roster: best at C, 1B, 2B, 3B, SS, LF, CF, RF, DH + top 6 SP + top 7 RP = 22 players
function getOptimizedRoster(orgName) {
  const orgPlayers = playersOf(orgName);
  const slots = ['C','1B','2B','3B','SS','LF','CF','RF','DH'];
  const optimized = [];
  const used = new Set();
  // For each position slot, pick the highest-value eligible player not yet used
  slots.forEach(slot => {
    // MGR-3: primary position first, then secondary/tertiary eligibility. gnFieldable30
    // covers by eligibility too; without the fallback an org with nobody whose PRIMARY
    // position is the slot simply left it empty -- Dirty Spikes fielded 21 of 22 with no
    // DH while Bryan Reynolds (RF, eligible RF/LF/DH, 994 RA) sat unused, understating
    // that one manager's bar against the other seven.
    let candidates = orgPlayers.filter(p => p.p === slot && !used.has(p.n));
    if (!candidates.length) {
      candidates = orgPlayers.filter(p => !used.has(p.n) && eligOf(p).includes(slot));
    }
    if (candidates.length > 0) {
      candidates = gnRankBy(candidates, getValue);
      optimized.push(candidates[0]);
      used.add(candidates[0].n);
    }
  });
  // Top 6 SPs
  const sps = gnRankBy(orgPlayers.filter(p => p.p === 'SP' && !used.has(p.n)), getValue).slice(0, 6);
  sps.forEach(p => { optimized.push(p); used.add(p.n); });
  // Top 7 RPs
  const rps = gnRankBy(orgPlayers.filter(p => p.p === 'RP' && !used.has(p.n)), getValue).slice(0, 7);
  rps.forEach(p => { optimized.push(p); used.add(p.n); });
  return optimized;
}

